using UnityEngine;

public class ColonyHealth : MonoBehaviour
{ public enum Team { Player, Ally, Enemy, Base, Home } public Team team = Team.Enemy; public float maxHealth = 100f; public float current; public float regenPerSecond; public float regenDelay = 5f; public bool invulnerable; float lastHurt = -999f; public bool IsDead => current <= 0f; public static bool Friendly(Team value) => value == Team.Player || value == Team.Ally || value == Team.Home; public Vector3 AimPoint => transform.position + Vector3.up * (team == Team.Base || team == Team.Home ? 1.1f : .48f); void Awake() { if (current <= 0f) { current = maxHealth; } } public void ResetHealth() { current = maxHealth; invulnerable = false; lastHurt = -999f; BroadcastHealth(); } public bool ApplyDamage(float amount, GameObject source) { if (invulnerable || IsDead || amount <= 0f) { return false; } var sourceHealth = source != null ? source.GetComponent<ColonyHealth>() : null; if (sourceHealth != null && Friendly(sourceHealth.team) == Friendly(team)) return false; float old = current; current = Mathf.Max(0f, current - amount); lastHurt = Time.time; if (team == Team.Player) EventDispatcher.SendEvent(GameEventTypes.ColonyEventType.Feedback, "Under fire! Use the furniture for cover."); BroadcastHealth(); if (current <= 0f && old > 0f) { if (team == Team.Player) { EventDispatcher.SendEventImmediate(GameEventTypes.PlayerEventType.Death, gameObject.GetInstanceID(), transform.position, current); } else { EventDispatcher.SendEventImmediate(GameEventTypes.NPCEventType.Death, gameObject.GetInstanceID(), transform.position, current); } } return true; } void Update() { if (IsDead || regenPerSecond <= 0f || ColonyGameDirector.Instance == null || !ColonyGameDirector.Instance.IsPlaying) { return; } if (Time.time - lastHurt < regenDelay) { return; } float old = current; current = Mathf.Min(maxHealth, current + regenPerSecond * Time.deltaTime); if (!Mathf.Approximately(old, current)) { BroadcastHealth(); } } void BroadcastHealth() { float pct = maxHealth <= 0f ? 0f : current / maxHealth; if (team == Team.Player) { EventDispatcher.SendEvent(GameEventTypes.PlayerEventType.HealthChanged, gameObject.GetInstanceID(), current, maxHealth, pct); EventDispatcher.SendEvent(GameEventTypes.UIEventType.PlayerHUDUpdated, gameObject.GetInstanceID(), current, maxHealth, pct); } else if (team == Team.Base) { EventDispatcher.SendEvent(GameEventTypes.ColonyEventType.AnthillHealthChanged, current, maxHealth); EventDispatcher.SendEvent(GameEventTypes.UIEventType.BossHUDUpdated, gameObject.GetInstanceID(), current, maxHealth, 0); } else if (team == Team.Home) { EventDispatcher.SendEvent(GameEventTypes.ColonyEventType.NestHealthChanged, current, maxHealth); } else { EventDispatcher.SendEvent(GameEventTypes.NPCEventType.HealthChanged, gameObject.GetInstanceID(), current, maxHealth, pct); } } }